-- Slaghammer finale: native stage7/TALK4/5s, scene1182/1551 and shared ward/barrier cleanup.
-- Requires matching quest-lifetime and RELATION_SUMMONED_BY6 core deployment; keep outside live updater until then.
-- Earlier intro follow remains OWNER_OR_SUMMONER23. Shared101430/103151 LINK2 remains unresolved.
SET @slaghammer_finale_concat=@@session.group_concat_max_len;
SET SESSION group_concat_max_len=1048576;
START TRANSACTION;
SET @slaghammer_finale_scripts=(SELECT SHA2(COALESCE(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entryorguid` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`source_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`id` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`link` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`Difficulties` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_phase_mask` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_chance` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_flags` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param6` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_x` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_y` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_z` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_o` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`comment` AS CHAR CHARACTER SET utf8mb4),'NULL')) ORDER BY `id` SEPARATOR '\n'),''),256) FROM smart_scripts WHERE entryorguid=101899 AND source_type=0);
SET @slaghammer_finale_conditions=(SELECT SHA2(COALESCE(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`SourceId` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`Comment` AS CHAR CHARACTER SET utf8mb4),'NULL')) ORDER BY `SourceGroup`,`ElseGroup`,`ConditionTypeOrReference` SEPARATOR '\n'),''),256) FROM conditions WHERE SourceTypeOrReferenceId=22 AND SourceEntry=101899);
SET @slaghammer_finale_old=(@slaghammer_finale_scripts='609c446581d398fa00dc89c8607fe292df381c0390aa34473756b462e7f73601' AND @slaghammer_finale_conditions='65148c3d76f35c6caee070eb0f7b829df092e5f145bad9d3881a6b5fc901784e');
SET @slaghammer_finale_applied=(@slaghammer_finale_scripts='fb018ba809a191e98f47b1b4c371624af9cfd47fd43d552b4a5879b7417bc1ad' AND @slaghammer_finale_conditions='35cc6f73a16af87bf5842c0dbdb65511028abec7c4b4d6290cabf0fa1aa63682');
SET @slaghammer_finale_safe=((@slaghammer_finale_old OR @slaghammer_finale_applied)
 AND (SELECT COUNT(*) FROM creature_template WHERE entry=101899 AND AIName='SmartAI' AND ScriptName='')=1
 AND (SELECT COUNT(*) FROM spell_script_names WHERE spell_id IN(201004,201321))=0
 AND (SELECT COUNT(*) FROM spell_scene WHERE MiscValue=1182)=1
 AND (SELECT COUNT(*) FROM spell_scene WHERE MiscValue=1182 AND SceneScriptPackageID=1551 AND PlaybackFlags=25 AND CustomDuration=0 AND ScriptName IS NULL)=1
 AND (SELECT COUNT(*) FROM spell_scene_event WHERE MiscValue=1182)=0);
SET @slaghammer_finale_guard=IF(COALESCE(@slaghammer_finale_safe,0),'DO 0','SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''Slaghammer finale source/conditions/binding/scene differ; review before updating''');
PREPARE slaghammer_finale_guard FROM @slaghammer_finale_guard;
EXECUTE slaghammer_finale_guard;
DEALLOCATE PREPARE slaghammer_finale_guard;
UPDATE smart_scripts SET action_type=86,action_param3=23,target_type=23,target_param1=0
WHERE @slaghammer_finale_safe AND @slaghammer_finale_old AND entryorguid=101899 AND source_type=0 AND id=9;
INSERT INTO conditions(SourceTypeOrReferenceId,SourceGroup,SourceEntry,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,Comment) SELECT 22,9,101899,31,0,4,0,0,'Slaghammer finale: actual Player' WHERE @slaghammer_finale_safe AND @slaghammer_finale_old;
INSERT INTO conditions(SourceTypeOrReferenceId,SourceGroup,SourceEntry,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,Comment) SELECT 22,9,101899,36,0,0,0,0,'Slaghammer finale: live Player' WHERE @slaghammer_finale_safe AND @slaghammer_finale_old;
INSERT INTO conditions(SourceTypeOrReferenceId,SourceGroup,SourceEntry,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,Comment) SELECT 22,9,101899,9,0,40710,0,0,'Slaghammer finale: active quest' WHERE @slaghammer_finale_safe AND @slaghammer_finale_old;
INSERT INTO conditions(SourceTypeOrReferenceId,SourceGroup,SourceEntry,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,Comment) SELECT 22,9,101899,15,0,16,0,0,'Slaghammer finale: Priest' WHERE @slaghammer_finale_safe AND @slaghammer_finale_old;
INSERT INTO conditions(SourceTypeOrReferenceId,SourceGroup,SourceEntry,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,Comment) SELECT 22,9,101899,33,1,0,6,0,'Slaghammer finale: actual summoner' WHERE @slaghammer_finale_safe AND @slaghammer_finale_old;
INSERT INTO conditions(SourceTypeOrReferenceId,SourceGroup,SourceEntry,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,Comment) SELECT 22,9,101899,22,1,1539,0,0,'Slaghammer finale: native map' WHERE @slaghammer_finale_safe AND @slaghammer_finale_old;
COMMIT;
SET SESSION group_concat_max_len=@slaghammer_finale_concat;
